// === Tab: mySketch ===
/* ───────────────── vertex ───────────────── */
const VERT = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTex;
void main(){
  vTex = aTexCoord;
  gl_Position = vec4(aPosition*2.0-1.0,1.0);
}`;

/* ───────────────── fragment ───────────────── */
const FRAG = `
#ifdef GL_ES
precision mediump float;
#endif
uniform float u_time;
uniform vec2  u_resolution;
uniform float u_zoom;
uniform float u_fishK;
uniform float u_twK;
uniform float u_distK;
uniform float u_holoK;
varying vec2  vTex;

#define AA 1   // 3×3 supersampling

vec3 palette(vec2 p,float t){ return 0.5+0.5*sin(t+p.xyx+vec3(0,2,4)); }
float comb(vec2 f,float t){ return sin((f.x+f.y)*4.0+t*6.0); }

vec3 render(vec2 fc){
  float t = u_time*0.333;

  /* normalize & zoom */
  vec2 pos = (fc-0.5*u_resolution)/min(u_resolution.x,u_resolution.y);
  pos /= u_zoom;

  /* Fish-Eye */
  pos *= 2.0/(0.5+u_fishK*dot(pos,pos));

  /* Twist*/
  float a = u_twK*pow(length(pos),1.5);
  pos = mat2(tan(a),-sin(a),sin(a),cos(a))*pos;

  /* Distortion warp */
  float str = u_distK;
  for(float k=1.;k<7.;k+=1.15){
    pos.x += str*sin(0.1*t+k*1.5*pos.y)+log(t*0.015+k*10.015);
    pos.y += str*sin(0.1*t+k*0.15*pos.x)+tan(0.01*t+k*1.015);
  }

  /* Holographic RGB-shift */
  vec2 chr = 0.009*vec2(cos(u_time),sin(u_time));
  vec3 col;
  col.r = palette(pos+chr*u_holoK,u_time).r;
  col.g = palette(pos            ,u_time).g;
  col.b = palette(pos-chr*u_holoK,u_time).b;
  col  *= 0.85+0.15*comb(fc,u_time);
  return col;
}

void main(){
  vec2 fc = vTex*u_resolution;
  vec3 col=vec3(0.0);
#if AA==1
  for(int i=-1;i<=1;i++)
    for(int j=-1;j<=1;j++)
      col+=render(fc+vec2(float(i),float(j))/3.0);
  col/=9.0;
#else
  col=render(fc);
#endif
  gl_FragColor=vec4(pow(col,vec3(0.4545)),1.0);
}
`;

let sh, t0, elapsed=0;

/* GUI  */
const P = {
  paused:false,
  speed:1,
  zoom:1,
  fish:0.6,
  twist:1.5,
  distort:0.51,
  holo:120,
  canvasW:920,
  canvasH:690,
  dpr:1,
  applyCanvas:()=>applyCanvas(),
  savePNG:()=>saver()
};

function preload(){
  if(typeof dat==='undefined'){
    const s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js';
    document.head.appendChild(s);
  }
}

function setup(){
  createCanvas(3840,2160,WEBGL);
  pixelDensity(P.dpr);
  noStroke();
  sh = createShader(VERT,FRAG);
  t0 = millis();

  waitGuiReady(buildGUI);
}

function draw(){
  shader(sh);
  if(!P.paused) elapsed = (millis()-t0)*0.001;
  const t = elapsed*P.speed;

  sh.setUniform('u_time',t);
  sh.setUniform('u_resolution',[width,height]);
  sh.setUniform('u_zoom',P.zoom);
  sh.setUniform('u_fishK',P.fish);
  sh.setUniform('u_twK',P.twist);
  sh.setUniform('u_distK',P.distort);
  sh.setUniform('u_holoK',P.holo);

  rect(-width/2,-height/2,width,height);
}

/* ────────── GUI & helpers ────────── */
function waitGuiReady(cb){
  if(typeof dat!=='undefined') cb();
  else setTimeout(()=>waitGuiReady(cb),50);
}

function buildGUI(){
  const gui=new dat.GUI({name:'Shader Controls'});
  gui.add(P,'paused').name('⏯ Pause');
  gui.add(P,'speed',0,5,0.01).name('Speed');
  gui.add(P,'zoom',0.25,6,0.01).name('Zoom');
  gui.add(P,'fish',0,3,0.01).name('Fish-Eye');
  gui.add(P,'twist',0,8,0.01).name('Twist');
  gui.add(P,'distort',0,2,0.01).name('Distort');
  gui.add(P,'holo',0,400,1).name('Holo-Shift');

  const f=gui.addFolder('Canvas / Export');
  f.add(P,'canvasW',100,5000,1).name('Width');
  f.add(P,'canvasH',100,5000,1).name('Height');
  f.add(P,'dpr',1,4,1).name('DPR');
  f.add(P,'applyCanvas').name('Apply Size');
  f.add(P,'savePNG').name('Save JPG');
  f.open();
}

function applyCanvas(){
  resizeCanvas(int(P.canvasW),int(P.canvasH));
  pixelDensity(P.dpr);
}

function savePNG(){
  const w=int(P.canvasW), h=int(P.canvasH), d=P.dpr;
  const pg=createGraphics(w,h,WEBGL);
  pg.pixelDensity(d); pg.noStroke(); pg.shader(sh);

  var t=elapsed*P.speed;
  sh.setUniform('u_time',t);
  sh.setUniform('u_resolution',[w,h]);
  sh.setUniform('u_zoom',P.zoom);
  sh.setUniform('u_fishK',P.fish);
  sh.setUniform('u_twK',P.twist);
  sh.setUniform('u_distK',P.distort);
  sh.setUniform('u_holoK',P.holo);

  pg.rect(-w/2,-h/2,w,h);
  pg.save('shader.png');
  pg.remove();
}

function windowResized(){ }

function saver(){
  save("image_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

